insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-buraczki', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-buraczki/0b3858b6-7aea-471e-8d89-2f66aac1edfd.webp', 20, 50, 4, null, null, '{}'::jsonb, '', array['post-sonntagsessen', 'post-panieren', 'post-smietana-schmand']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-buraczki', 'de', 'Buraczki', 'buraczki', 'Warme geraspelte Rote-Bete-Beilage mit leichter Mehlschwitze und Apfel, klassisch zum Sonntagsschnitzel, klar zu unterscheiden von Botwinka, Barszcz und kalter Ćwikła.', '[{"text":"Rote Bete waschen und ungeschält in Salzwasser weich kochen, oder bereits vorgekochte Bete verwenden. Abkühlen lassen, schälen und grob raspeln oder in feine Streifen schneiden.","tip":"Das ist eine Beilage und keine Suppe. Die Suppen [Botwinka](/de/rezepte/botwinka) und [Barszcz](/de/rezepte/barszcz-czerwony) bleiben eigene Rezepte mit ganz anderer Konsistenz."},{"text":"Zwiebel fein würfeln und in Butter oder Öl glasig dünsten. Einen Esslöffel Mehl einstreuen und 1 bis 2 Minuten hell anschwitzen, das ist die Zasmażka. Die Bete dazugeben, mit einem Schuss Wasser und einer Prise Zucker 8 bis 10 Minuten warm ziehen lassen.","tip":"Die Schwitze bindet die Beilage, ohne sie zur Suppe zu machen. Wer die Bete lieber kalt und scharf mit Meerrettich anrührt, findet das bei [Ćwikła](/de/rezepte/cwikla)."},{"text":"Einen sauren Apfel raspeln und unterheben. Mit Salz, Pfeffer und etwas Essig oder Zitrone abschmecken. Optional Meerrettich vom Herd nehmen und erst dann unterrühren, sonst verkocht die Schärfe.","tip":"Meerrettich in der warmen Beilage ist Hausvariante, nicht Pflicht. Wie Śmietana getrennt dazu passt, zeigt der Guide zu [Śmietana und Schmand](/de/blog/smietana-schmand)."},{"text":"Heiß oder lauwarm neben Schnitzel und Kartoffeln servieren, ohne die Beilage zu Brei zu kochen.","tip":"Klassisch dazu passt [Kotlet schabowy](/de/rezepte/kotlet-schabowy). Nicht mit dem kalten Mayo-Festsalat [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa) verwechseln, und nicht mit Oster-Ćwikła."}]'::jsonb, 'Buraczki, erdig-süß und säuerlich, warm auf dem Teller, eine Beilage und keine Suppe. Rote Bete ist in Polen seit dem 16. Jahrhundert dokumentiert, schon der Dichter und Gutsherr Mikołaj Rej beschrieb damals ein eingelegtes Rezept, das dem heutigen Ćwikła nahekommt. Als eigenständiges Wurzelgemüse gewann die Bete in der Renaissance an Bedeutung, als italienische Techniken der Gemüsezubereitung an polnischen Höfen Einzug hielten, und ihre Frostresistenz sowie einfache Lagerung in Erdmieten machten sie zu einem festen Winterlebensmittel. Die Technik des Zasmażanie, also das Anschwitzen mit einer Mehlschwitze aus Butter und Mehl, geht auf französische Kücheneinflüsse an adligen Höfen zurück, die sich in den Teilungszeiten mit ländlicher Tradition vermischten. Erst nach dem Zweiten Weltkrieg wurden Buraczki zum festen Pflichtbestandteil der PRL-Milchbars, dort untrennbar verbunden mit dem panierten Kotlet mielony und Kartoffelpüree. Das ist weder die Suppe aus jungen Beten [Botwinka](/de/rezepte/botwinka) noch die klare oder cremige Rote-Bete-Suppe [Barszcz czerwony](/de/rezepte/barszcz-czerwony) noch der kalte Mayo-Festsalat [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa), sondern eine warme Beilage, klassisch neben [Kotlet schabowy](/de/rezepte/kotlet-schabowy).

## Einkaufen und kochen

Rote Bete roh oder vorgekocht, Zwiebel, ein saurer Apfel, Mehl für die helle Zasmażka und Butter oder Öl, oft günstig im [Polenladen](/de/blog/polenladen-einkaufen). Salz, Pfeffer, eine Prise Zucker und etwas Essig oder Zitrone runden ab. Meerrettich ist optional und näher an [Ćwikła](/de/rezepte/cwikla). Wie du Śmietana separat dazu servierst, zeigt der Guide zu [Śmietana und Schmand](/de/blog/smietana-schmand). Wer eigentlich eine Bete-Suppe sucht, findet die bei [Botwinka](/de/rezepte/botwinka) oder [Barszcz](/de/rezepte/barszcz-czerwony).

Die Bete wird weich gekocht oder fertig vorgekocht verwendet, geschält und geraspelt, Handschuhe schützen dabei die Hände vor Verfärbung. Die Zwiebel zieht glasig an, danach kommt ein Esslöffel Mehl für eine helle Zasmażka, erst dann die Bete mit wenig Flüssigkeit. Der Apfel kommt gegen Ende dazu. Optionaler Meerrettich erst vom Herd, sonst verkocht die Schärfe. Zu viel Wasser macht daraus schnell eine kleine Suppe und rückt die Beilage optisch zu nah an Botwinka oder Barszcz heran. Am Ende braucht es eine ausgewogene Balance aus Säure, Salz und einer Prise Süße, serviert wird heiß.

Vorgekochte Bete aus der Vakuumpackung spart nach der Schicht wertvolle Zeit, das lässt sich auch ganz ehrlich so sagen. Die Farbe färbt schnell ab, deshalb schützen ein separates Brett und notfalls Handschuhe die Küche. Kinder dürfen den Apfel raspeln. Reste halten sich gut im Kühlschrank und lassen sich am Folgetag kurz erhitzen, den Rahmen für den ganzen Sonntag liefert der Guide zum [Sonntagsessen](/de/blog/sonntagsessen-polnisch).

## Am Tisch

Heiß neben [Kotlet schabowy](/de/rezepte/kotlet-schabowy), Kartoffeln oder Kasza, Śmietana separat in einem Schälchen dazu. Der Menüplatz steht im [polnischen Sonntagsessen](/de/blog/sonntagsessen-polnisch), Panier-Technik liefert der [Panieren-Guide](/de/blog/panieren-schabowy). Die kalte Oster-Bete bleibt [Ćwikła](/de/rezepte/cwikla), gemischt werden sollte die Beilage nicht mit der ganz anders aufgebauten [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa).

Zu viel Flüssigkeit macht aus der Beilage schnell eine kleine Suppe, die optisch an [Botwinka](/de/rezepte/botwinka) oder [Barszcz](/de/rezepte/barszcz-czerwony) erinnert, ohne deren Charakter zu haben. Ohne Mehlschwitze bleibt sie oft wässrig statt sämig. Wer sie mit der kalten [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa) oder mit [Ćwikła](/de/rezepte/cwikla) verwechselt, erwartet fälschlich Salat oder Relish statt einer warmen Beilage. Meerrettich von Anfang an mitzukochen verkocht seine Schärfe.

Mit Apfel bleibt die warme Linie klassisch, Meerrettich erst vom Herd ist Hausvariante. Wer stattdessen einen kalten Relish aus Bete und Meerrettich sucht, findet den bei [Ćwikła](/de/rezepte/cwikla). Passende Nachbarn sind [Schabowy](/de/rezepte/kotlet-schabowy), die Suppe [Botwinka](/de/rezepte/botwinka), [Barszcz](/de/rezepte/barszcz-czerwony) und [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa), dazu passende Guides sind das [Sonntagsessen](/de/blog/sonntagsessen-polnisch), das [Panieren](/de/blog/panieren-schabowy) und die [Śmietana](/de/blog/smietana-schmand).', 'Buraczki Rezept | Rote-Bete-Beilage polnisch | Alemniam', 'Warme polnische Rote-Bete-Beilage (buraczki zasmażane) mit leichter Mehlschwitze und Apfel, klassisch zum Schabowy. Auch mit vorgekochter Bete.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-buraczki', 'pl', 'Buraczki', 'buraczki', 'Ciepły dodatek z tartych buraków na zasmażce z jabłkiem, klasycznie do schabowego w niedzielę, wyraźnie inny niż botwinka, barszcz i zimna ćwikła.', '[{"text":"Buraki umyj i ugotuj w skórce w osolonej wodzie, albo użyj gotowanych. Ostudź, obierz i zetrzyj grubo lub pokrój w cienkie paski.","tip":"To dodatek, a nie zupa. Zupy [botwinka](/pl/rezepte/botwinka) i [barszcz](/pl/rezepte/barszcz-czerwony) zostają osobnymi przepisami o zupełnie innej konsystencji."},{"text":"Cebulę drobno pokrój i zeszklij na maśle lub oleju. Wsyp łyżkę mąki i podsmaż 1 do 2 minut na jasno, to zasmażka. Dodaj buraki, odrobinę wody i szczyptę cukru, duś 8 do 10 minut na ciepło.","tip":"Zasmażka spaja dodatek, nie robiąc z niego zupy. Kto woli zimny, ostry burak z chrzanem, znajdzie go w [ćwikle](/pl/rezepte/cwikla)."},{"text":"Zetrzyj kwaśne jabłko i wmieszaj. Dopraw solą, pieprzem i odrobiną octu lub cytryny. Opcjonalny chrzan dodaj po zdjęciu z ognia, inaczej ostrość się wygotuje.","tip":"Chrzan w ciepłym dodatku to wariant domu, nie obowiązek. Jak dobrać śmietanę osobno, pokazuje przewodnik [śmietana czy schmand](/pl/blog/smietana-czy-schmand)."},{"text":"Podawaj gorące lub letnie obok kotleta i ziemniaków, bez rozgotowania na papkę.","tip":"Klasycznie pasuje do [kotleta schabowego](/pl/rezepte/kotlet-schabowy). Nie myl z zimną majonezową [sałatką jarzynową](/pl/rezepte/salatka-jarzynowa) ani z wielkanocną ćwikłą."}]'::jsonb, 'Buraczki, ziemisto-słodkie i kwaszone, ciepłe na talerzu, dodatek, a nie zupa. Burak ćwikłowy jest w Polsce udokumentowany już od XVI wieku, poeta i ziemianin Mikołaj Rej opisywał wtedy przepis na kiszone buraczki, bliski dzisiejszej ćwikle. Jako samodzielne warzywo korzeniowe burak zyskał na znaczeniu w okresie odrodzenia, gdy na polskie dwory trafiły włoskie techniki obróbki warzyw, a jego odporność na mróz i łatwość przechowywania w kopcach uczyniły go stałym elementem zimowej kuchni. Technika zasmażania, czyli podprażania na zasmażce z masła i mąki, wywodzi się z francuskich wpływów na szlacheckich dworach, które z czasem połączyły się z wiejską tradycją. Dopiero po drugiej wojnie światowej buraczki zasmażane stały się obowiązkowym daniem w barach mlecznych PRL-u, nierozerwalnie związanym z panierowanym kotletem mielonym i tłuczonymi ziemniakami. To ani zupa z młodych buraków [botwinka](/pl/rezepte/botwinka), ani [barszcz czerwony](/pl/rezepte/barszcz-czerwony), ani zimna majonezowa [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa), tylko ciepły dodatek, klasycznie obok [kotleta schabowego](/pl/rezepte/kotlet-schabowy).

## Zakupy i gotowanie

Buraki surowe lub gotowane, cebula, kwaśne jabłko, mąka na jasną zasmażkę oraz masło lub olej, często korzystnie w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Sól, pieprz, szczypta cukru i odrobina octu lub cytryny domykają smak. Chrzan jest opcjonalny i bliższy [ćwikle](/pl/rezepte/cwikla). Jak podać śmietanę osobno, pokazuje przewodnik [śmietana czy schmand](/pl/blog/smietana-czy-schmand). Kto właściwie szuka zupy z buraków, znajdzie ją w [botwince](/pl/rezepte/botwinka) lub w [barszczu](/pl/rezepte/barszcz-czerwony).

Buraki gotuje się do miękkości albo używa gotowych, obiera i ściera, rękawiczki chronią ręce przed zabarwieniem. Cebula dusi się do szklistości, potem łyżka mąki na jasną zasmażkę, dopiero potem buraki z małą ilością płynu. Jabłko dodaje się pod koniec. Opcjonalny chrzan dopiero po zdjęciu z ognia, inaczej ostrość się wygotuje. Za dużo wody zamienia danie w małą zupkę i wizualnie zbliża je do botwinki lub barszczu. Na końcu liczy się balans kwasu, soli i szczypty słodyczy, podaje się na gorąco.

Gotowane buraki z próżniowego opakowania oszczędzają czas po zmianie, i można to śmiało uczciwie przyznać. Kolor szybko się przenosi, dlatego osobna deska, a czasem i rękawiczki, chronią kuchnię. Dzieci mogą zetrzeć jabłko. Resztki dobrze trzymają się w lodówce i nadają się do krótkiego podgrzania następnego dnia, ramę na całą niedzielę daje przewodnik [obiad niedzielny](/pl/blog/obiad-niedzielny).

## Przy stole

Gorące obok [schabowego](/pl/rezepte/kotlet-schabowy), ziemniaków lub kaszy, śmietana osobno w miseczce. Miejsce w menu daje [obiad niedzielny](/pl/blog/obiad-niedzielny), o panierce opowiada [poradnik panierowania](/pl/blog/panierowanie-kotlet). Zimny burak wielkanocny zostaje przy [ćwikle](/pl/rezepte/cwikla), nie warto ich mieszać z zupełnie inaczej zbudowaną [sałatką jarzynową](/pl/rezepte/salatka-jarzynowa).

Za dużo płynu szybko zamienia dodatek w małą zupkę, przypominającą wyglądem [botwinkę](/pl/rezepte/botwinka) lub [barszcz](/pl/rezepte/barszcz-czerwony), bez ich charakteru. Bez zasmażki zostaje często wodnisty zamiast gęsty. Mylenie z zimną [sałatką jarzynową](/pl/rezepte/salatka-jarzynowa) albo z [ćwikłą](/pl/rezepte/cwikla) prowadzi do błędnego oczekiwania sałatki lub relishu zamiast ciepłego dodatku. Dodanie chrzanu od samego początku gotowania wygotowuje jego ostrość.

Z jabłkiem ciepła linia zostaje klasyczna, chrzan po zdjęciu z ognia to wariant domu. Kto szuka zimnego relishu z buraka i chrzanu, znajdzie go w [ćwikle](/pl/rezepte/cwikla). Pasującymi sąsiadami są [schabowy](/pl/rezepte/kotlet-schabowy), zupa [botwinka](/pl/rezepte/botwinka), [barszcz](/pl/rezepte/barszcz-czerwony) i [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa), a dobrymi przewodnikami [obiad niedzielny](/pl/blog/obiad-niedzielny), [panierowanie](/pl/blog/panierowanie-kotlet) i [śmietana](/pl/blog/smietana-czy-schmand).', 'Buraczki przepis | Ciepły dodatek z buraków | Alemniam', 'Ciepły polski dodatek z buraków (buraczki zasmażane) na lekkiej zasmażce z jabłkiem, klasycznie do schabowego. Także z gotowanymi burakami.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
